import{_ as e,o as l,c as i,a2 as o}from"./chunks/framework.C-si7TFR.js";const u=JSON.parse('{"title":"条件判断","description":"工作流中的条件判断，也称为分支逻辑，就是IF-ELSE逻辑，允许工作流根据特定条件自动选择不同的执行路径，支持使用变量表达式动态决策。","frontmatter":{"title":"条件判断","description":"工作流中的条件判断，也称为分支逻辑，就是IF-ELSE逻辑，允许工作流根据特定条件自动选择不同的执行路径，支持使用变量表达式动态决策。","meta":[{"name":"keywords","content":"条件判断, IF-ELSE, 分支逻辑, 排他性网关, 低代码, AI工作流, 流程引擎"}]},"headers":[],"relativePath":"zh/if.md","filePath":"zh/if.md"}'),t={name:"zh/if.md"};function r(n,a,p,h,s,c){return l(),i("div",null,[...a[0]||(a[0]=[o('<h2 id="条件判断" tabindex="-1">条件判断 <a class="header-anchor" href="#条件判断" aria-label="Permalink to &quot;条件判断&quot;">​</a></h2><p>工作流中的条件判断，也称为分支逻辑，就是IF-ELSE逻辑，允许工作流根据特定条件自动选择不同的执行路径。根据输入判断输出是真或假，并选择对应分支执行。支持搭配使用且和或组合条件，并且可使用变量表达式在运行时动态决策。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h2 id="入参" tabindex="-1">入参 <a class="header-anchor" href="#入参" aria-label="Permalink to &quot;入参&quot;">​</a></h2><h3 id="条件关系" tabindex="-1">条件关系 <a class="header-anchor" href="#条件关系" aria-label="Permalink to &quot;条件关系&quot;">​</a></h3><p>可以通过且、或关系组成复杂的条件组合。如果组合中同时出现且和或，其关系如下：<code>CondX 且 CondY 或 CondZ...</code></p><ul><li><p>且</p><p>当且仅当所有条件（条件1、条件2....条件N）都为真才返回真，否则为假</p></li><li><p>或</p><p>只要任意一个条件为真，则为真，否则全部为假则为假</p></li></ul><h3 id="条件数值类型" tabindex="-1">条件数值类型 <a class="header-anchor" href="#条件数值类型" aria-label="Permalink to &quot;条件数值类型&quot;">​</a></h3><p>当前支持布尔值、日期和时间、数字、字符串四种类型的数值类型对比。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><p>值1和值2可以时常量，也可以时变量表达式（在运行时动态获取当前值）</p><h4 id="布尔值" tabindex="-1">布尔值 <a class="header-anchor" href="#布尔值" aria-label="Permalink to &quot;布尔值&quot;">​</a></h4><p>判断值1是否为真或假（值2这里无用）</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h4 id="日期和时间" tabindex="-1">日期和时间 <a class="header-anchor" href="#日期和时间" aria-label="Permalink to &quot;日期和时间&quot;">​</a></h4><p>比较值1和值2两者日期之间的关系，可以对比yyyy-mm-dd hh:mm:ss这样的字符串格式，也可以对比unix秒时间戳格式</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h4 id="数字" tabindex="-1">数字 <a class="header-anchor" href="#数字" aria-label="Permalink to &quot;数字&quot;">​</a></h4><p>对比值1和值2两个数字之间的大小关系，包括：</p><ul><li>大于</li><li>大于等于</li><li>小于</li><li>小于等于</li><li>等于</li><li>不等于</li></ul><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h4 id="字符串" tabindex="-1">字符串 <a class="header-anchor" href="#字符串" aria-label="Permalink to &quot;字符串&quot;">​</a></h4><p>对比值1和值2两个字符串之间的关系，包括：</p><ul><li>包含</li><li>不包含</li><li>以...开始</li><li>不以...开始</li><li>以...结尾</li><li>不以...结尾</li><li>相等</li><li>不相等</li></ul><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h2 id="出参" tabindex="-1">出参 <a class="header-anchor" href="#出参" aria-label="Permalink to &quot;出参&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[true/false]</span></span></code></pre></div><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote>',28)])])}const b=e(t,[["render",r]]);export{u as __pageData,b as default};
